css:
.pkf-root{position:absolute;inset:0;overflow:hidden;background:var(--wa-bg, #05050a);z-index:5;font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-size:16px;font-weight:400;font-style:normal;line-height:normal;letter-spacing:normal;color:var(--wa-text, #fff);text-align:left;text-transform:none;word-spacing:normal;-webkit-font-smoothing:antialiased}
.pkf-root,.pkf-root *,.pkf-root *::before,.pkf-root *::after{box-sizing:border-box}
.pkf-root *{margin:0;padding:0;border:0 solid transparent;background:none;font:inherit;color:inherit;text-decoration:none}
.pkf-root img{display:block;border:0;max-width:none}
.pkf-root [hidden]{display:none!important}
.pkf-root .n10_9492{background-color:color-mix(in srgb, var(--wa-surface, rgb(207 209 212)) 10%, transparent);align-content:stretch;display:flex;gap:12px;align-items:center;padding-left:16px;padding-right:16px;padding-top:7px;padding-bottom:7px;position:relative;border-radius:8px;flex-shrink:0}
.pkf-root .n10_9493{position:relative;flex-shrink:0;width:16px;height:16px}
.pkf-root .x93{position:absolute;display:block;inset:0;max-width:none;width:100%;height:100%}
.pkf-root .n10_9495{word-break:break-word;font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:500;line-height:20px;font-style:normal;position:relative;flex-shrink:0;color:var(--wa-text-sub, #cfd1d4);font-size:14px;white-space:nowrap;width:49px}
.pkf-root[data-theme="light"]{background:var(--wa-bg, #eef2f7);color:var(--wa-text, #0e1a2b)}
.pkf-root[data-theme="light"] [data-name="Background"] > img{filter:invert(1) hue-rotate(180deg) saturate(0.4) brightness(1.05);opacity:0.5}
.pkf-root[data-theme="light"] [data-name="Building Image"] img{filter:saturate(0.92) brightness(0.98)}
.pkf-root[data-theme="light"] [data-name="Floor Plan"] img{filter:invert(1) hue-rotate(180deg) saturate(0.55) brightness(1.04)}
.pkf-root[data-theme="light"] [data-name^="Popup/"] > [data-name="Background"]::after{content:"";position:absolute;inset:0;border-radius:inherit;background:color-mix(in srgb, var(--wa-bg, rgb(247 250 254)) 92%, transparent);pointer-events:none}
.pkf-root[data-theme="light"] .n10_9492{background-color:color-mix(in srgb, var(--wa-surface, rgb(116 123 134)) 10%, transparent)}
.pkf-root[data-theme="light"] .n10_9495{color:var(--wa-text-sub, #33353a)}
